use crate::{firewall,network,upnp};
use eframe::egui::{self,Color32,RichText};

const GREEN:Color32=Color32::from_rgb(76,190,115);
const BG:Color32=Color32::from_rgb(12,16,21);
const PANEL:Color32=Color32::from_rgb(20,26,34);

#[derive(PartialEq)] enum Page{Overview,Adapters,Connections,Firewall,Upnp}
pub struct NetworkManagerApp{
 page:Page, adapters:Vec<network::Adapter>, rules:Vec<firewall::Rule>, connections:String, devices:Vec<upnp::Device>,
 selected:usize,status:String,rule_name:String,rule_port:String,proto:String,ext:String,intp:String,client:String,desc:String
}
impl NetworkManagerApp{
 pub fn new(_: &eframe::CreationContext<'_>)->Self{let mut x=Self{page:Page::Overview,adapters:vec![],rules:vec![],connections:String::new(),devices:vec![],selected:0,status:"Ready".into(),rule_name:"Malachite Allow".into(),rule_port:"25565".into(),proto:"TCP".into(),ext:"25565".into(),intp:"25565".into(),client:"192.168.1.100".into(),desc:"MalachiteVR Network Manager".into()};x.reload();x}
 fn reload(&mut self){self.adapters=network::adapters().unwrap_or_default();self.rules=firewall::rules().unwrap_or_default();self.status="Refreshed".into();}
 fn side(&mut self,u:&mut egui::Ui){u.set_width(230.);u.vertical_centered(|u|{u.add_space(20.);u.label(RichText::new("MALACHITEVR").size(25.).strong().color(GREEN));u.label(RichText::new("NETWORK MANAGER").small().color(Color32::GRAY));});u.add_space(25.);
  for (p,n) in [(Page::Overview,"Overview"),(Page::Adapters,"Network Adapters"),(Page::Connections,"Connections"),(Page::Firewall,"Windows Firewall"),(Page::Upnp,"UPnP / Port Forwarding")]{let s=self.page==p;if u.add_sized([210.,42.],egui::Button::new(RichText::new(n).color(if s{Color32::WHITE}else{Color32::from_gray(175)}).strong()).fill(if s{Color32::from_rgb(32,62,48)}else{Color32::TRANSPARENT})).clicked(){self.page=p;}}
  u.with_layout(egui::Layout::bottom_up(egui::Align::LEFT),|u|{u.separator();u.label(RichText::new("MalachiteeVR • Windows").small().color(Color32::GRAY));});
 }
 fn card(u:&mut egui::Ui,t:&str,v:&str,s:&str){egui::Frame::group(u.style()).fill(PANEL).corner_radius(10).inner_margin(16.).show(u,|u|{u.label(RichText::new(t).small().color(Color32::GRAY));u.label(RichText::new(v).size(25.).strong());u.label(RichText::new(s).small().color(Color32::GRAY));});}
 fn overview(&mut self,u:&mut egui::Ui){u.heading("Network overview");u.label("One control center for your Windows networking stack.");u.add_space(18.);
  u.horizontal(|u|{Self::card(u,"ADAPTERS",&self.adapters.len().to_string(),"detected");u.add_space(10.);Self::card(u,"ACTIVE",&self.adapters.iter().filter(|x|x.status=="Up").count().to_string(),"online");u.add_space(10.);Self::card(u,"FIREWALL",&self.rules.len().to_string(),"rules visible");u.add_space(10.);Self::card(u,"UPnP",&self.devices.len().to_string(),"gateways found");});
  u.add_space(22.);egui::Frame::group(u.style()).fill(PANEL).corner_radius(10).inner_margin(18.).show(u,|u|{u.heading("Quick actions");u.horizontal(|u|{if u.button("Refresh").clicked(){self.reload()}if u.button("Discover UPnP").clicked(){match upnp::discover(){Ok(d)=>{self.devices=d;self.status=format!("Found {} UPnP gateway(s)",self.devices.len())},Err(e)=>self.status=e.to_string()}}if u.button("Connections").clicked(){self.page=Page::Connections}if u.button("Firewall").clicked(){self.page=Page::Firewall}});});u.add_space(15.);u.label(RichText::new(&self.status).small().color(Color32::GRAY));}
 fn adapters(&mut self,u:&mut egui::Ui){u.heading("Network adapters");if u.button("Refresh").clicked(){self.reload()}u.add_space(12.);egui::Grid::new("ad").striped(true).show(u,|u|{for h in ["Name","Status","Speed","MAC","Actions"] { u.strong(h); } u.end_row();for a in self.adapters.clone(){u.label(&a.name);u.label(RichText::new(&a.status).color(if a.status=="Up"{GREEN}else{Color32::GRAY}));u.label(&a.speed);u.label(a.mac.unwrap_or_default());if u.button(if a.status=="Up"{"Disable"}else{"Enable"}).clicked(){let _=network::toggle(&a.name,a.status!="Up");self.reload()}u.end_row();}});}
 fn connections(&mut self,u:&mut egui::Ui){u.heading("Current TCP connections");if u.button("Refresh").clicked(){self.connections=network::connections().unwrap_or_default()}u.add_space(10.);egui::ScrollArea::both().show(u,|u|u.monospace(if self.connections.is_empty(){"Press Refresh."}else{&self.connections}));}
 fn firewall(&mut self,u:&mut egui::Ui){u.heading("Windows Firewall");u.label("Administrator access is required for changes.");u.add_space(10.);u.horizontal(|u|{u.text_edit_singleline(&mut self.rule_name);u.text_edit_singleline(&mut self.rule_port);egui::ComboBox::from_id_salt("proto").selected_text(&self.proto).show_ui(u,|u|{u.selectable_value(&mut self.proto,"TCP".into(),"TCP");u.selectable_value(&mut self.proto,"UDP".into(),"UDP");});if u.button("Allow inbound").clicked(){if let Ok(p)=self.rule_port.parse(){let _=firewall::add(&self.rule_name,p,&self.proto);self.reload()}}});u.add_space(12.);
  egui::ScrollArea::vertical().show(u,|u|{egui::Grid::new("fw").striped(true).show(u,|u|{u.strong("Rule");u.strong("Direction");u.strong("Action");u.strong("Enabled");u.end_row();for r in self.rules.clone(){u.label(&r.name);u.label(&r.direction);u.label(&r.action);u.label(&r.enabled);if u.button("Delete").clicked(){let _=firewall::remove(&r.name);self.reload()}u.end_row();}})});}
 fn upnp(&mut self,u:&mut egui::Ui){u.heading("UPnP / port forwarding");u.label("Discover compatible Internet Gateway Devices and create NAT mappings.");if u.button("Discover gateways").clicked(){match upnp::discover(){Ok(d)=>{self.devices=d;self.selected=0;self.status=format!("Found {} gateway(s)",self.devices.len())},Err(e)=>self.status=e.to_string()}}u.add_space(10.);
  for (i,d) in self.devices.iter().enumerate(){u.selectable_value(&mut self.selected,i,format!("Gateway {} • {}",i+1,d.server));u.small(&d.location);}
  if !self.devices.is_empty(){u.add_space(10.);egui::Frame::group(u.style()).fill(PANEL).corner_radius(10).inner_margin(15.).show(u,|u|{egui::Grid::new("up").num_columns(2).show(u,|u|{u.label("External");u.text_edit_singleline(&mut self.ext);u.end_row();u.label("Internal");u.text_edit_singleline(&mut self.intp);u.end_row();u.label("Private IP");u.text_edit_singleline(&mut self.client);u.end_row();u.label("Description");u.text_edit_singleline(&mut self.desc);u.end_row();});u.horizontal(|u|{for p in ["TCP","UDP"]{if u.button(format!("Add {p} mapping")).clicked(){let r=(||->anyhow::Result<()>{upnp::add(&self.devices[self.selected],self.ext.parse()?,self.intp.parse()?,p,&self.client,&self.desc)})();self.status=match r{Ok(_)=>"UPnP mapping created".into(),Err(e)=>format!("UPnP error: {e}")}}}});});}u.add_space(10.);u.label(RichText::new(&self.status).small().color(Color32::GRAY));}
}
impl eframe::App for NetworkManagerApp{fn update(&mut self,ctx:&egui::Context,_:&mut eframe::Frame){ctx.set_visuals(egui::Visuals::dark());egui::SidePanel::left("side").resizable(false).frame(egui::Frame::NONE.fill(BG).inner_margin(10.)).show(ctx,|u|self.side(u));egui::CentralPanel::default().frame(egui::Frame::NONE.fill(BG).inner_margin(28.)).show(ctx,|u|match self.page{Page::Overview=>self.overview(u),Page::Adapters=>self.adapters(u),Page::Connections=>self.connections(u),Page::Firewall=>self.firewall(u),Page::Upnp=>self.upnp(u)});ctx.request_repaint_after(std::time::Duration::from_secs(2));}}

